#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int, int> P;
const ll mod = 1000000009;

ll mod_pow(ll base, ll exp, ll m = mod) {
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % m;
        base = base * base % m;
        exp >>= 1;
    }
    return result;
}

struct ModInt {
    ll value;
    ModInt() : value(0) {}
    ModInt(ll v) {
        value = v % mod;
        if (value < 0) value += mod;
    }
    operator int() const { return (int)value; }
    ModInt& operator+=(const ModInt& other) {
        value += other.value;
        if (value >= mod) value -= mod;
        return *this;
    }
    ModInt& operator-=(const ModInt& other) {
        value -= other.value;
        if (value < 0) value += mod;
        return *this;
    }
    ModInt& operator*=(const ModInt& other) {
        value = (value * other.value) % mod;
        return *this;
    }
    friend ModInt operator+(ModInt a, const ModInt& b) { return a += b; }
    friend ModInt operator-(ModInt a, const ModInt& b) { return a -= b; }
    friend ModInt operator*(ModInt a, const ModInt& b) { return a *= b; }
    friend ModInt operator^(ModInt a, ll n) {
        ModInt res(1);
        while (n > 0) {
            if (n & 1) res *= a;
            a *= a;
            n >>= 1;
        }
        return res;
    }
};

ll inv(ll a, ll p) {
    if (a == 1) return 1;
    return (1 - p * inv(p % a, a)) / a + p;
}

const int MAXN = 262144;
ModInt fact[MAXN], inv_fact[MAXN];

void init_factorials() {
    fact[0] = ModInt(1);
    for (int i = 1; i < MAXN; i++) {
        fact[i] = fact[i - 1] * ModInt(i);
    }
    inv_fact[MAXN - 1] = ModInt(1) / fact[MAXN - 1];
    for (int i = MAXN - 2; i >= 0; i--) {
        inv_fact[i] = inv_fact[i + 1] * ModInt(i + 1);
    }
}

ModInt comb(int a, int b) {
    if (a < 0 || b < 0 || a < b) return ModInt(0);
    return fact[a] * inv_fact[b] * inv_fact[a - b];
}

pair<ModInt, ModInt> multiply_pairs(pair<ModInt, ModInt> a, pair<ModInt, ModInt> b) {
    return {a.first * b.first, a.second * b.first + a.first * b.second};
}

pair<ModInt, ModInt> add_pairs(pair<ModInt, ModInt> a, pair<ModInt, ModInt> b) {
    return {a.first + b.first, a.second + b.second};
}

pair<ModInt, ModInt> dp[501];
bool used[501];

void initialize() {
    init_factorials();
    dp[0] = {ModInt(1), ModInt(0)};
    dp[1] = {ModInt(2), ModInt(0)};
    for (int n = 2; n <= 500; n++) {
        for (int j = 0; j < n; j++) {
            ModInt count = ModInt(n + 1);
            ModInt sum = ModInt(0);
            for (int k = 0; k < n; k++) {
                sum += abs(j - k);
            }
            auto left = dp[j];
            auto right = dp[n - 1 - j];
            auto x = multiply_pairs(left, right);
            x.first *= comb(n - 1, j);
            x.second *= comb(n - 1, j);
            x.first *= count;
            x.second *= count + sum;
            dp[n] = add_pairs(dp[n], x);
        }
    }
}

pair<ModInt, ModInt> dp2[502][501];

void solve() {
    int n, m; cin >> n >> m;
    initialize();
    for (int i = 0; i <= n; i++) {
        for (int k = 0; k <= m; k++) {
            dp2[i][k] = {ModInt(0), ModInt(0)};
        }
    }
    dp2[0][0] = {ModInt(1), ModInt(0)};
    for (int i = 0; i < n; i++) {
        for (int k = 0; k <= m; k++) {
            if (dp2[i][k].first.value == 0 && dp2[i][k].second.value == 0) continue;
            for (int j = i; j < n; j++) {
                int ni = j + 2;
                if (ni > n) ni = n;
                int nk = k + j - i + 1;
                if (nk <= m) {
                    auto x = multiply_pairs(dp2[i][k], dp[j - i + 1]);
                    x.first *= comb(nk, k);
                    x.second *= comb(nk, k);
                    dp2[ni][nk] = add_pairs(dp2[ni][nk], x);
                }
            }
            if (i + 1 <= n && k <= m) {
                dp2[i + 1][k] = add_pairs(dp2[i + 1][k], dp2[i][k]);
            }
        }
    }
    cout << (int)dp2[n][m].second << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve();
    return 0;
}
